import pytesseract
from PIL import Image
import re

def extract_items_from_image(image_path, extraction_type):
    # Preprocess image
    image = Image.open(image_path)
    processed = preprocess_image(image)

    # Run OCR
    text = pytesseract.image_to_string(processed)

    # Parse text
    items = parse_food_items(text, extraction_type)

    # Enhance with LLM if low confidence
    if items['confidence'] < 0.7:
        items = enhance_with_llm(text)

    return {
        'extractedText': text,
        'parsedItems': items['items'],
        'confidence': items['confidence']
    }

def parse_food_items(text, type):
    # Regex patterns for common formats
    patterns = {
        'item': r'([A-Za-z\s]+)\s+(\d+\.?\d*)\s*(kg|g|L|ml|pcs)',
        'date': r'(\d{1,2}[-/]\d{1,2}[-/]\d{2,4})'
    }

    items = []
    for match in re.finditer(patterns['item'], text):
        items.append({
            'itemName': match.group(1).strip(),
            'quantity': float(match.group(2)),
            'unit': match.group(3)
        })

    return {'items': items, 'confidence': 0.8}

