use Illuminate\Support\Facades\Http;

class AIServiceClient
{
    private $baseUrl;

    public function __construct()
    {
        $this->baseUrl = config('services.ai.url', 'http://localhost:5000');
    }

    public function analyzePatterns($userId, $daysBack = 30)
    {
        $response = Http::timeout(60)->post("{$this->baseUrl}/analyze-patterns", [
            'userId' => $userId,
            'daysBack' => $daysBack
        ]);

        if ($response->failed()) {
            throw new \Exception('AI service request failed');
        }

        return $response->json();
    }

    public function optimizeMealPlan($userId, $weekStart, $preferences = null)
    {
        $response = Http::timeout(120)->post("{$this->baseUrl}/optimize-meal-plan", [
            'userId' => $userId,
            'weekStartDate' => $weekStart,
            'customPreferences' => $preferences
        ]);

        return $response->json();
    }
}

