class AIAnalysisController extends Controller
{
    private $aiService;

    public function __construct(AIServiceClient $aiService)
    {
        $this->aiService = $aiService;
    }

    public function analyzePatterns(Request $request)
    {
        try {
            $result = $this->aiService->analyzePatterns(
                $request->user()->id,
                $request->input('daysBack', 30)
            );

            ConsumptionPattern::create([
                'user_id' => $request->user()->id,
                'analysis_date' => now(),
                'weekly_trends' => $result['weeklyTrends'],
                'over_consumption' => $result['overConsumption'],
                'under_consumption' => $result['underConsumption'],
                'waste_risk_items' => $result['wasteRiskItems']
            ]);

            return response()->json($result);
        } catch (\Exception $e) {
            return response()->json(['error' => $e->getMessage()], 500);
        }
    }
}

