use OpenAI\Laravel\Facades\OpenAI;

class ChatbotController extends Controller
{
    public function sendMessage(Request $request)
    {
        $request->validate([
            'sessionId' => 'required|string',
            'message' => 'required|string|max:1000'
        ]);

        $session = ChatSession::firstOrCreate(
            ['session_id' => $request->sessionId, 'user_id' => $request->user()->id],
            ['messages' => []]
        );

        $messages = $session->messages ?? [];
        $messages[] = ['role' => 'user', 'content' => $request->message];

        $context = $this->buildContext($request->user());
        $systemPrompt = $this->buildSystemPrompt($context);

        $response = OpenAI::chat()->create([
            'model' => 'gpt-3.5-turbo',
            'messages' => [
                ['role' => 'system', 'content' => $systemPrompt],
                ...$messages
            ],
            'temperature' => 0.7,
            'max_tokens' => 500
        ]);

        $botReply = $response['choices'][0]['message']['content'];
        $messages[] = ['role' => 'assistant', 'content' => $botReply];

        if (count($messages) > 20) {
            $messages = array_slice($messages, -20);
        }

        $session->update(['messages' => $messages]);

        return response()->json(['reply' => $botReply]);
    }

    private function buildContext($user)
    {
        $inventory = $user->inventories()->take(10)->get();
        $recentLogs = $user->consumptionLogs()->latest()->take(5)->get();

        return [
            'inventory' => $inventory->pluck('item_name')->join(', '),
            'recentLogs' => $recentLogs->pluck('item_name')->join(', '),
            'preferences' => $user->dietary_preferences
        ];
    }

    private function buildSystemPrompt($context)
    {
        return "You are NourishBot, an AI assistant helping users reduce food waste and improve nutrition. 
                The user currently has: {$context['inventory']}. 
                Recently consumed: {$context['recentLogs']}. 
                Dietary preferences: " . json_encode($context['preferences']) . ". 
                Provide practical, concise advice. Be friendly and action-oriented.";
    }
}

